head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.btnOpenPopup_onclick = function(e) {
    openPopup();
};
scwin._hasClass = function(id) {
    if (!scwin.__getDom($p.id + id)) {
        return false;
    }
    return true;
}
scwin.__isDisabled = function(id) {
    var className = scwin.__getDom($p.id + id).className;
    return className.indexOf("w2tabcontrol_disabled") >= 0;
}
scwin.setValue = function() {
    if (((j) => j.length ? j : $('#mf_popup_closeButton'))($('#popup_closeButton')).length == 0) {
        wfm_popup_popup_closeButton.click();
    } else {
        popup_closeButton.click();
    }
}

scwin.onpageload = function() {
    openPopup = function() {
        window.options = {
            "src": "tabControl_Disable_WEF-115_(WSQ-1404)_popup.xml",
            "style": "position:absolute; top:0; width:100%; height:100%; z-index:9001"
        };
        WebSquare.layer.showModal();
        WebSquare.util.dynamicCreate("wfm_popup", "wframe", options);
    };
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Feb-2018
    //End unitTest
}
